def minDeletionsToCancel(s):
    n = len(s)
    same = [[k for k in range(i + 1, n) if s[k] == s[i]] for i in range(n)]
    f = [[0] * (n + 2) for _ in range(n + 2)]
    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n + 1):
            best = f[i + 1][j]
            for k in same[i]:
                if k >= j:
                    break
                cand = 2 + f[i + 1][k] + f[k + 1][j]
                if cand > best:
                    best = cand
            f[i][j] = best
    return n - f[0][n]
